"""The small provider contract used by the Cloud Library."""
from dataclasses import dataclass
from pathlib import Path
import re
from typing import Protocol
from urllib.parse import urlparse


CATEGORIES = {'songs': 'Songs', 'images': 'Images', 'custom': 'Custom Slides',
              'media': 'Media', 'presentations': 'Presentations', 'themes': 'Themes'}


def friendly_name(name):
    """Hide file extensions and identifiers generated by earlier Library Sync uploads."""
    name = Path(name.replace('\\', '/')).stem
    return re.sub(r' \[[0-9a-f]{12}\]$', '', name).strip() or 'Untitled item'


class SyncError(Exception):
    """An error safe to display without exposing credentials or response bodies."""


def preview_url_allowed(value):
    """Providers validate viewer destinations; the UI only opens HTTPS browser links."""
    url = urlparse(value)
    return url.scheme == 'https' and bool(url.hostname) and not url.username and not url.password


@dataclass(frozen=True)
class CloudItem:
    id: str
    name: str
    folder: bool = False
    size: int = 0
    modified: str = ''
    can_upload: bool = False
    can_download: bool = True
    checksum: str = ''
    version: str = ''
    category: str = ''
    preview_url: str = ''
    thumbnail_url: str = ''
    resource_key: str = ''
    title: str = ''
    can_copy: bool = False
    can_edit: bool = False
    can_delete: bool = False
    created: str = ''
    parents: tuple[str, ...] = ()
    can_move: bool = False

    @property
    def display_name(self):
        return (self.title or (self.name if self.folder else friendly_name(self.name))).strip()


class CloudProvider(Protocol):
    """Providers keep networking, permission checks and atomic writes off the UI thread."""

    def sign_in(self, cancel, open_browser): ...
    def disconnect(self): ...
    def folder(self, folder_id, resource_key='') -> CloudItem: ...
    def type_folder(self, folder, category, create=True) -> CloudItem | None: ...
    def list_folder(self, folder, page_token='') -> tuple[list[CloudItem], str]: ...
    def create_folder(self, folder, category, name) -> CloudItem: ...
    def find_item(self, folder, category, title, exclude='') -> CloudItem | None: ...
    def rename(self, item, folder, title) -> CloudItem: ...
    def delete(self, item): ...
    def copy(self, item, folder) -> CloudItem: ...
    def move(self, item, folder) -> CloudItem: ...
    def preview(self, item, cancel) -> tuple[str, bytes]: ...
    def stream(self, item, byte_range, cancel): ...
    def download(self, item, destination, cancel, progress): ...
    def upload(self, folder, category, source, cancel, progress, title='', overwrite=None) -> CloudItem: ...
    def close(self): ...
